// Disposable local runner: load the unchanged Vitest configuration without bundling it.
import { startVitest } from 'vitest/node';
globalThis.__dirname = process.cwd();
const { default: config } = await import('./vitest.config.ts');
const ctx = await startVitest('test', process.argv.slice(2), {
  ...config.test,
  run: true,
  config: false,
  root: `${process.cwd()}/apps/www`,
  include: ['src/**/*.test.ts'],
  testNamePattern: process.env.CODEBOX_TEST_NAME,
}, { plugins: config.plugins, css: { postcss: {} } });
await ctx?.close();

